#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int n;
    scanf("%d", &n);
    int *v = malloc(n * sizeof(int));
    int total = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &v[i]);
        total += v[i];
    }
    printf("%d\n", total);
    free(v);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int n;
    scanf("%d", &n);
    int *v = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", v + i);
    }
    for (int *p = v + n - 1; p >= v; p--) {
        printf("%d%s", *p, p == v ? "\n" : " ");
    }
    free(v);
    return 0;
}
